def amicable_numbers_sum(limit: int) -> int:
    """
    Sum all amicable numbers from 1 to a specified number.

    Two numbers are amicable if:
    - The sum of proper divisors of a equals b, and
    - The sum of proper divisors of b equals a, and
    - a != b

    Proper divisors of n are all divisors of n except n itself.
    """
    if limit < 2:
        return 0

    # Precompute sum of proper divisors for all numbers up to limit
    # Using a sieve-like approach
    sum_of_divisors = [0] * (limit + 1)

    for i in range(1, limit + 1):
        for j in range(2 * i, limit + 1, i):
            sum_of_divisors[j] += i

    # Now find all amicable numbers
    amicable_set = set()
    for a in range(1, limit + 1):
        b = sum_of_divisors[a]
        if b <= limit and b != a:
            if sum_of_divisors[b] == a:
                amicable_set.add(a)
                amicable_set.add(b)

    return sum(amicable_set)

