def find_solution(a: int, b: int, n: int):
    """
    Find integers x and y such that a*x + b*y = n.
    Returns a tuple (x, y) if a solution exists, otherwise returns None.
    """
    from math import gcd

    # Handle edge cases
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        return None

    if a == 0:
        if n % b == 0:
            return (0, n // b)
        return None

    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        return None

    g = gcd(a, b)

    # A solution exists if and only if g divides n
    if n % g != 0:
        return None

    # Use the extended Euclidean algorithm to find x0, y0 such that a*x0 + b*y0 = g
    def extended_gcd(aa, bb):
        """Return (g, x, y) such that aa*x + bb*y = g = gcd(aa, bb)"""
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            return (g, y1, x1 - (aa // bb) * y1)

    g, x0, y0 = extended_gcd(a, b)

    # Scale the solution by n/g
    factor = n // g
    x = x0 * factor
    y = y0 * factor

    return (x, y)
